(1829121, 251732, 33379, '<td valign="top">thats excellent</td>', 'thats excellent', '2005-11-01 06:36:06.000000', NULL, 1),
(1829127, 251462, 35602, '<td valign="top">Had to really look on this one, but when I found the face I was amazed at the effect you got.  The lighting on this one really creates an almost negative appearance.  Very nice job.</td>', 'Had to really look on this one, but when I found the face I was amazed at the effect you got.  The lighting on this one really creates an almost negative appearance.  Very nice job.', '2005-11-01 06:49:38.000000', NULL, 1),
(1829131, 251956, 42840, '<td valign="top">u did that all by urself? amazing. 10 points!</td>', 'u did that all by urself? amazing. 10 points!', '2005-11-01 06:55:33.000000', NULL, 1),
(1829133, 251994, 35602, '<td valign="top">I am a big Lord of The Rings fan.  Loved your interpretation.  The only thing that you could do is apply a noise reduction filter because the shadow in the background has a lot of distracting spots.</td>', 'I am a big Lord of The Rings fan.  Loved your interpretation.  The only thing that you could do is apply a noise reduction filter because the shadow in the background has a lot of distracting spots.', '2005-11-01 06:56:49.000000', NULL, 1),
