(1829172, 251983, 36908, '<td valign="top">great carving</td>', 'great carving', '2005-11-01 07:12:46.000000', NULL, 1),
(1829173, 251983, 15855, '<td valign="top">very cool...</td>', 'very cool...', '2005-11-01 07:12:52.000000', NULL, 1),
(1829174, 251960, 36908, '<td valign="top">I love the lighting</td>', 'I love the lighting', '2005-11-01 07:13:29.000000', NULL, 1),
(1829176, 251995, 35602, '<td valign="top">Very cool effect.</td>', 'Very cool effect.', '2005-11-01 07:14:34.000000', NULL, 1),
(1829177, 251596, 15855, '<td valign="top">lots of unique pumpkins..very few good photographs , your''s is one of the best</td>', 'lots of unique pumpkins..very few good photographs , your''s is one of the best', '2005-11-01 07:14:39.000000', NULL, 1),
(1829179, 251597, 35602, '<td valign="top">Carving is extradinary and intricate.  The lighting doesn''t seem to be creating enough impact, though.  I also thought the corn didn''t do much to enhance the pumpkins.</td>', 'Carving is extradinary and intricate.  The lighting doesn''t seem to be creating enough impact, though.  I also thought the corn didn''t do much to enhance the pumpkins.', '2005-11-01 07:16:43.000000', NULL, 1),
(1829183, 251975, 36908, '<td valign="top">awesome carving</td>', 'awesome carving', '2005-11-01 07:18:44.000000', NULL, 1),
(1829184, 251525, 35602, '<td valign="top">Traditional to the max.  Loved the use of the candy in this one.  Very good image for Halloween and composition is perfect.   A little too much noise, though in the lit up faces.</td>', 'Traditional to the max.  Loved the use of the candy in this one.  Very good image for Halloween and composition is perfect.   A little too much noise, though in the lit up faces.', '2005-11-01 07:18:51.000000', NULL, 1),
(1829186, 251571, 36908, '<td valign="top">awesome capture, great snapshot</td>', 'awesome capture, great snapshot', '2005-11-01 07:19:23.000000', NULL, 1),
(1829187, 251937, 35602, '<td valign="top">Like the abstract nature of this one.  Needed to reduce the noise, though.  It realy is strong around the candle and the edges of the black.</td>', 'Like the abstract nature of this one.  Needed to reduce the noise, though.  It realy is strong around the candle and the edges of the black.', '2005-11-01 07:20:26.000000', NULL, 1),
(1829188, 251430, 15855, '<td valign="top">nice use of light</td>', 'nice use of light', '2005-11-01 07:21:04.000000', NULL, 1),
