(1843086, 251732, 16488, '<td valign="top">Well controlled. Super sharp. Interesting smoke element in the background--ads to the humor. Carving, while not "expert" jack-o-lantern school technique, is well fit for your subject. Lighting sweet!</td>', 'Well controlled. Super sharp. Interesting smoke element in the background--ads to the humor. Carving, while not "expert" jack-o-lantern school technique, is well fit for your subject. Lighting sweet!', '2005-11-06 21:52:47.000000', NULL, 1),
(1843087, 251865, 16488, '<td valign="top">Oooh! I love the hostility of this image! Far better than letting some punk steal your precious carving off the front porch while you sleep and waking up to it smashed in the center of the street! Take control of your pumpkin''s fate! =o</td>', 'Oooh! I love the hostility of this image! Far better than letting some punk steal your precious carving off the front porch while you sleep and waking up to it smashed in the center of the street! Take control of your pumpkin''s fate! =o', '2005-11-06 21:54:24.000000', NULL, 1),
(1843089, 251866, 16488, '<td valign="top">Love the way this fills the frame--the round pumpkin in the square hole! ;-)</td>', 'Love the way this fills the frame--the round pumpkin in the square hole! ;-)', '2005-11-06 21:54:59.000000', NULL, 1),
(1843091, 251948, 16488, '<td valign="top">Best carved pumpkins of the bunch! I like the way you''ve given the context of a grand and modern(?) porch. Lighting is perfect...but then, you probably know that.</td>', 'Best carved pumpkins of the bunch! I like the way you''ve given the context of a grand and modern(?) porch. Lighting is perfect...but then, you probably know that.', '2005-11-06 21:56:21.000000', NULL, 1),
(1843092, 251993, 16488, '<td valign="top">Nicely on theme!</td>', 'Nicely on theme!', '2005-11-06 21:57:08.000000', NULL, 1),
(1843099, 251031, 16488, '<td valign="top">Nicely conceived! I think your pumpkin appears to be a bit too willing to shoot rather than rot...a tad bit too content perhaps. But the lights are out inside and figuratively... Is that ketchup? Classic gore!</td>', 'Nicely conceived! I think your pumpkin appears to be a bit too willing to shoot rather than rot...a tad bit too content perhaps. But the lights are out inside and figuratively... Is that ketchup? Classic gore!', '2005-11-06 21:59:17.000000', NULL, 1),
(1843103, 251884, 16488, '<td valign="top">You must have gone for the lighter fluid! Excellent! I love the way the flames shoot out and the complexity of the inferno in the mouth!</td>', 'You must have gone for the lighter fluid! Excellent! I love the way the flames shoot out and the complexity of the inferno in the mouth!', '2005-11-06 22:02:52.000000', NULL, 1),
