(1845849, 251278, 16488, '<td valign="top">I like the addition of glow to the outside of the pumpkin. I might have left the underside un-done, though, as I think it makes it float when it doesn''t seem like it should. Appropriately gross, however.</td>', 'I like the addition of glow to the outside of the pumpkin. I might have left the underside un-done, though, as I think it makes it float when it doesn''t seem like it should. Appropriately gross, however.', '2005-11-07 20:28:51.000000', NULL, 1),
(1845851, 251975, 39979, '<td valign="top">wow great pic and overall effect</td>', 'wow great pic and overall effect', '2005-11-07 20:29:19.000000', NULL, 1),
(1845852, 251598, 16488, '<td valign="top">Interesting effect with the light painting. Wish you''d given the subject more breathing space...feels a bit tight on the crop.</td>', 'Interesting effect with the light painting. Wish you''d given the subject more breathing space...feels a bit tight on the crop.', '2005-11-07 20:29:42.000000', NULL, 1),
(1845855, 251823, 16488, '<td valign="top">Intricately carved. I like the lighting on the outside of the pumpkin...gives it appropriate form and texture.</td>', 'Intricately carved. I like the lighting on the outside of the pumpkin...gives it appropriate form and texture.', '2005-11-07 20:30:25.000000', NULL, 1),
(1845856, 251808, 16488, '<td valign="top">You win for the oddest carving, in my book! Looks like a Christmas ornament!<br/>Did you use power tools???</td>', 'You win for the oddest carving, in my book! Looks like a Christmas ornament!Did you use power tools???', '2005-11-07 20:31:14.000000', NULL, 1),
(1845860, 251946, 16488, '<td valign="top">Like the bats! Not sure if it''s the exposure time that causes the edges to go soft or if it''s truly lacking focus....</td>', 'Like the bats! Not sure if it''s the exposure time that causes the edges to go soft or if it''s truly lacking focus....', '2005-11-07 20:33:40.000000', NULL, 1),
(1845861, 251944, 16488, '<td valign="top">Now that''s an ugly pumpkin! Well done!</td>', 'Now that''s an ugly pumpkin! Well done!', '2005-11-07 20:34:05.000000', NULL, 1),
(1845864, 251960, 16488, '<td valign="top">Oh, I sooo under-appreciated this on my first pass! I love the flames and the shape of the surroundings as they''re lit up by the light! Nicely carved! Sweet! (bumping up!)</td>', 'Oh, I sooo under-appreciated this on my first pass! I love the flames and the shape of the surroundings as they''re lit up by the light! Nicely carved! Sweet! (bumping up!)', '2005-11-07 20:35:16.000000', NULL, 1),
