(1845872, 251972, 16488, '<td valign="top">Intricately carved! I love all the faces in the castle image! Some distracting elements (table, pumpkin behind, plate)...If it were just a bit more crisp in focus and a little less noisy it would be a more satisfying image.</td>', 'Intricately carved! I love all the faces in the castle image! Some distracting elements (table, pumpkin behind, plate)...If it were just a bit more crisp in focus and a little less noisy it would be a more satisfying image.', '2005-11-07 20:38:28.000000', NULL, 1),
(1845873, 251956, 36999, '<td valign="top">Nice collection of carvings, good exposure too!  Fun to have so many pumkins in the image</td>', 'Nice collection of carvings, good exposure too!  Fun to have so many pumkins in the image', '2005-11-07 20:38:45.000000', NULL, 1),
(1845877, 251732, 36999, '<td valign="top">neat idea with the smoke</td>', 'neat idea with the smoke', '2005-11-07 20:40:06.000000', NULL, 1),
