(1845917, 251823, 36999, '<td valign="top">way cool carving</td>', 'way cool carving', '2005-11-07 20:50:23.000000', NULL, 1),
(1845918, 250537, 16488, '<td valign="top">Cute idea! Has the innocence of halloween all over it! I think you could have cropped off the left and bottom and given us more pixels to appreciate your clever set up.</td>', 'Cute idea! Has the innocence of halloween all over it! I think you could have cropped off the left and bottom and given us more pixels to appreciate your clever set up.', '2005-11-07 20:50:28.000000', NULL, 1),
