(1845940, 251988, 16488, '<td valign="top">Reminds me of those deep-sea diving helmets! A fairly odd carving...not sure what the reference is....but it''s all in fun, anyway!</td>', 'Reminds me of those deep-sea diving helmets! A fairly odd carving...not sure what the reference is....but it''s all in fun, anyway!', '2005-11-07 20:59:40.000000', NULL, 1),
(1845971, 251358, 38267, '<td valign="top">Not the most difficult carve some might think, but I like all the processing you did and the overall shot.  Good luck.</td>', 'Not the most difficult carve some might think, but I like all the processing you did and the overall shot.  Good luck.', '2005-11-07 21:19:53.000000', NULL, 1),
